dding:35px clamp(16px,4.4vw,70px) 25px}.intro{display:flex;justify-content:space-between;align-items:center;padding:0 4px 26px}.eyebrow,.section-kicker{font:10px var(--mono);color:#9a9aa0;letter-spacing:1.3px}.eyebrow{display:flex;align-items:center;gap:10px}.eyebrow-line{width:32px;height:1px;background:#686866}.intro h1{font:900 clamp(48px,6.6vw,82px)/.88 var(--display);letter-spacing:-1px;margin:12px 0 11px;color:var(--cream)}.intro h1 i{font-style:normal;color:var(--acid)}.intro p{font-size:13px;color:#a1a1a4;margin:0}.intro p strong{color:#dedbd2;font-weight:600}.lab-stamp{border:1px solid #4d4e42;color:#b8c17d;padding:8px 11px 6px;display:grid;grid-template-columns:1fr 30px;column-gap:5px;align-items:center;transform:rotate(3deg);font:8px/1.25 var(--mono);letter-spacing:.5px;text-align:center}.lab-stamp b{font:23px var(--body);grid-column:2;grid-row:1/3;color:var(--acid)}.lab-stamp small{font-size:6px;color:#888b70;grid-column:1}.game-layout{display:grid;grid-template-columns:minmax(220px,.83fr) minmax(365px,1.3fr) minmax(270px,1fr);gap:13px;align-items:stretch}.panel{background:linear-gradient(145deg,#1b1c20,#17181b);border:1px solid var(--line);position:relative;min-width:0}.panel-head{padding:17px 17px 11px;display:flex;justify-content:space-between;align-items:center}.panel-head h2,.collection-head h2{font:800 22px/.95 var(--display);letter-spacing:.65px;margin:6px 0 0}.panel-head h2>span,.collection-head h2>span{font:10px var(--mono);vertical-align:middle;background:#2e3031;color:var(--acid);padding:3px 5px;margin-left:4px}.icon-btn{border:1px solid #3c3d40;background:#222327;color:#b2b2ab;width:29px;height:29px;font-size:19px;cursor:pointer;transition:.2s}.icon-btn:hover{color:var(--acid);border-color:var(--acid);transform:rotate(-40deg)}.armory-sub{font:8px var(--mono);color:#777981;padding:1px 17px 12px;letter-spacing:.35px}.weapon-list{padding:0 10px 8px;display:grid;gap:6px}.weapon-card{--weapon:#d4fc57;position:relative;display:grid;grid-template-columns:60px 1fr 24px;align-items:center;gap:8px;min-height:66px;background:#222327;border:1px solid #333439;padding:6px 7px;cursor:pointer;text-align:left;color:var(--cream);transition:transform .16s,border .16s,background .16s;overflow:hidden}.weapon-card:before{content:'';position:absolute;inset:0 auto 0 0;width:2px;background:var(--weapon);opacity:.7}.weapon-card:hover{border-color:#777a67;transform:translateX(2px);background:#292a2e}.weapon-card.selected{border-color:var(--weapon);background:#2b2d2b;box-shadow:inset 0 0 16px color-mix(in srgb,var(--weapon) 8%,transparent)}.weapon-card.equipped:after{content:'TESTING';position:absolute;top:3px;right:27px;font:7px var(--mono);letter-spacing:.6px;color:var(--acid)}.gun-icon{height:47px;display:grid;place-items:center;background:radial-gradient(ellipse at center,#383a37,#28292a 70%);color:var(--weapon);overflow:hidden}.gun-icon svg{width:58px;height:34px;filter:drop-shadow(0 2px 3px #0008)}.weapon-copy{min-width:0}.weapon-name{display:block;font:800 17px/.95 var(--display);letter-spacing:.35px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.weapon-type{display:block;margin-top:4px;font:8px var(--mono);letter-spacing:.4px;color:#8f9091;white-space:nowrap}.weapon-statline{height:3px;background:#38393c;margin-top:6px;max-width:72px}.weapon-statline i{display:block;height:100%;background:var(--weapon)}.card-check{width:17px;height:17px;border:1px solid #535459;display:grid;place-items:center;color:var(--acid);font-size:11px}.selected .card-check{background:var(--weapon);border-color:var(--weapon);color:#171812}.boneyard-footer{border-top:1px solid #2c2d31;margin:1px 11px 0;padding:10px 2px 11px;display:flex;align-items:center;gap:7px;font:7px var(--mono);letter-spacing:.35px;color:#6d6e74}.tiny-square{width:6px;height:6px;background:var(--orange)}.forge-panel{overflow:hidden}.forge-head{padding-bottom:13px}.machine-status,.range-tag{font:8px var(--mono);letter-spacing:.5px;color:#9da18a;border:1px solid #3f433