y);letter-spacing:.6px;color:var(--slot-color,var(--acid));margin-top:7px;text-align:center;max-width:90%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.fusion-slot .slot-gun-type{font:7px var(--mono);color:#a1a296;margin-top:2px}.fusion-slot.filled .slot-plus{display:none}.fusion-slot .remove-slot{position:absolute;right:6px;top:3px;color:#8a8b83;font:13px var(--body)}.plus-sign{font:24px var(--display);color:#77786e;text-align:center}.beam-line{z-index:1;display:flex;align-items:center;gap:8px;margin:14px 0 12px;font:7px var(--mono);color:#88897c;letter-spacing:1px}.beam-line span{height:1px;background:#45473d;flex:1}.beam-line b{font-weight:400}.output-slot{height:111px;border:1px solid #45473b;position:relative;z-index:1;background:radial-gradient(ellipse at 50% 62%,#35372d,#20211f 70%);display:grid;place-items:center;overflow:hidden}.output-slot:before{content:'';position:absolute;width:116px;height:116px;border:1px solid #535544;border-radius:50%;box-shadow:0 0 0 9px #aaa72d08,0 0 0 19px #aaa72d08;opacity:.55}.output-placeholder{display:flex;align-items:center;flex-direction:column;color:#a3a392;font:9px var(--mono);letter-spacing:.8px;z-index:1}.output-spark{font-size:24px;color:#666957;line-height:25px}.output-placeholder small{font-size:7px;color:#696a60;margin-top:5px}.output-slot.has-result{border-color:var(--result-color,var(--acid));animation:resultPop .48s cubic-bezier(.2,.8,.2,1)}.result-weapon{z-index:1;display:flex;align-items:center;gap:12px;animation:fadeUp .3s ease}.result-weapon .gun-icon{width:80px;height:59px;background:#34362f}.result-weapon .gun-icon svg{width:77px;height:47px}.result-name{font:900 26px/.9 var(--display);max-width:190px;color:var(--result-color,var(--acid));text-transform:uppercase}.result-type{font:8px var(--mono);letter-spacing:.4px;color:#b6b5a8;margin-top:6px}.result-badge{display:inline-block;border:1px solid currentColor;padding:2px 4px;font:7px var(--mono);margin-top:5px;color:var(--result-color,var(--acid